/**
 * shopfront's dashboards as the All dashboards gallery reads them (U6e):
 * ListDashboards with descriptions, a preview panel each, last-viewed times
 * and every source (built-in, generated by forge, from the repo, saved in
 * Reliant), and QueryPanel answers for the cards' previews (`gallery-*`
 * panels: 24 hourly points each, a deterministic wave).
 *
 * Registered by wrapping the merged table (withDashboardFixtures), so its
 * QueryPanel answers its own panels and hands every other one to whatever
 * answered before it.
 */
import type { Fixture, Fixtures } from '../rpc'
import { DAY, FIXED_NOW, HOUR, MIN, USER, iso } from './base'

type Source = 'BUILTIN' | 'GENERATED' | 'REPO' | 'WORKSPACE'

/** A preview panel the card runs as a sparkline. */
const preview = (key: string, signal: 'traces' | 'metrics' | 'logs' = 'traces') => ({
  id: `gallery-${key}`, title: key, kind: 'line', signal, series: [{ label: 'A', agg: 'count' }],
})

const dashboard = (source: Source, key: string, title: string, description: string, o: { viewed?: number; panels?: number; starred?: boolean; tags?: string[]; group?: string; noPreview?: boolean; category?: string } = {}) => ({
  ref: { source: `DASHBOARD_SOURCE_${source}`, projectId: 'shopfront', key },
  source: `DASHBOARD_SOURCE_${source}`,
  title, description,
  readOnly: source !== 'WORKSPACE',
  starred: !!o.starred,
  lastViewedAt: o.viewed === undefined ? undefined : iso(o.viewed),
  panelCount: o.panels ?? 6,
  previewPanels: o.noPreview ? [] : [preview(key)],
  tags: o.tags ?? [], group: o.group ?? '', category: o.category ?? '',
  release: source === 'GENERATED' || source === 'REPO'
    ? { releaseVersion: '20261118.121200-a1b2c3d4e5f6', shippedAt: iso(3 * HOUR), filePath: source === 'REPO' ? `deploy/observability/dashboards/${key}.json` : '', envIds: [] }
    : undefined,
  workspace: source === 'WORKSPACE'
    ? { version: 3, createdBy: { id: USER.id, name: USER.name, email: USER.email }, updatedBy: { id: USER.id, name: USER.name, email: USER.email }, updatedAt: iso(2 * DAY), envIds: [] }
    : undefined,
})

const SHOPFRONT = [
  dashboard('BUILTIN', 'overview', 'Overview', 'The whole project at a glance', { viewed: 20 * MIN, panels: 8, category: 'standard', group: 'overview' }),
  dashboard('BUILTIN', 'releases', 'Releases', 'How each release changed errors and latency', { viewed: 3 * DAY, panels: 5, category: 'standard', group: 'releases' }),
  dashboard('BUILTIN', 'workloads', 'Workloads', 'Replicas, restarts, CPU and memory', { panels: 6, category: 'standard', group: 'platform' }),
  dashboard('GENERATED', 'product-overview', 'shopfront: product overview', 'Visitors, sign-ups and conversion', { viewed: 5 * HOUR, panels: 7, group: 'product' }),
  dashboard('GENERATED', 'users', 'shopfront: users', '', { panels: 5, group: 'product' }),
  dashboard('GENERATED', 'product', 'shopfront: product', '', { panels: 6, group: 'product' }),
  dashboard('GENERATED', 'acquisition', 'shopfront: acquisition', '', { panels: 4, group: 'product' }),
  dashboard('GENERATED', 'service-api', 'shopfront: api', 'Requests, errors and latency of api', { viewed: DAY, group: 'services' }),
  dashboard('GENERATED', 'service-worker', 'shopfront: worker', 'Throughput and failures of worker', { group: 'services' }),
  dashboard('REPO', 'checkout-funnel', 'Checkout funnel', 'Cart to paid order, by step and payment method', { viewed: 2 * HOUR, starred: true, panels: 9, tags: ['checkout', 'revenue'] }),
  dashboard('REPO', 'inventory-sync', 'Inventory sync', 'How far the inventory mirror trails the supplier feed', { panels: 4, tags: ['worker'] }),
  dashboard('WORKSPACE', 'order-latency', 'Order latency', 'p50/p95/p99 of order placement, by region', { viewed: 40 * MIN, starred: true, panels: 3 }),
  dashboard('WORKSPACE', 'on-call', 'On-call', 'What the on-call rotation watches first', { panels: 6, tags: ['ops'] }),
  dashboard('WORKSPACE', 'launch-notes', 'Launch notes', 'Notes for the holiday launch; text only', { panels: 2, noPreview: true }),
]

const at = (ago: number) => new Date(FIXED_NOW - ago).toISOString()

/** A preview's answer: one line of 24 hourly points, shaped per dashboard. */
export function dashboardsQueryPanel(req: Record<string, unknown>): Record<string, unknown> | undefined {
  const panel = (req.panel ?? {}) as { id?: string }
  const id = String(panel.id ?? '')
  if (!id.startsWith('gallery-')) return undefined
  const key = id.slice('gallery-'.length)
  // A key with no traffic yet draws the card's "No data" state.
  if (key === 'inventory-sync') return { panelId: id, kind: 'line', unit: '', stepSeconds: 3600, series: [] }
  const seed = [...key].reduce((acc, c) => acc + c.charCodeAt(0), 0)
  const base = 40 + (seed % 60)
  return {
    panelId: id, kind: 'line', unit: '', stepSeconds: 3600,
    series: [{
      label: 'A', group: {}, value: 0,
      points: Array.from({ length: 24 }, (_, i) => ({
        time: at((23 - i) * HOUR),
        value: Math.round(base * (1 + 0.35 * Math.sin((i + (seed % 7)) / (2.4 + (seed % 3)))) * 100) / 100,
        partial: i === 23,
      })),
    }],
  }
}

/** The table with the gallery's answers laid over it: its own QueryPanel panels first, then the previous answer. */
export function withDashboardFixtures(base: Fixtures): Fixtures {
  const previous = base['controlplane.v1.ObservabilityService/QueryPanel'] as Fixture | undefined
  const listPrevious = base['controlplane.v1.DashboardService/ListDashboards'] as Fixture | undefined
  const call = (fixture: Fixture | undefined, req: Record<string, unknown>) => (typeof fixture === 'function' ? fixture(req) : fixture ?? {})
  return {
    ...base,
    'controlplane.v1.ObservabilityService/QueryPanel': (req) => dashboardsQueryPanel(req) ?? call(previous, req),
    'controlplane.v1.DashboardService/ListDashboards': (req) => (req.projectId === 'shopfront' ? { dashboards: SHOPFRONT, canWrite: true } : call(listPrevious, req)),
  }
}
